// Extract request data
const body = $input.first().json.body;
return {
  city: body.city || 'Phoenix',
  origin: body.origin || 'Downtown',
  destination: body.destination || 'Airport',
  distance_miles: body.distance_miles || 15,
  timestamp: new Date().toISOString()
};

// Simulate weather data (replace with API call in production)
const city = $input.first().json.city;
const hour = new Date().getHours();

let temp = 75;
let conditions = 'Clear';
let multiplier = 1.0;
let reasoning = 'Normal weather';

// City-based simulation
if (city.toLowerCase().includes('new york')) {
  temp = 45;
  if (Math.random() > 0.5) {
    conditions = 'Rain';
    multiplier = 1.25;
    reasoning = 'Rain increases demand';
  }
} else if (city.toLowerCase().includes('phoenix')) {
  temp = hour > 10 && hour < 18 ? 105 : 85;
  if (temp > 100) {
    multiplier = 1.15;
    reasoning = 'Extreme heat';
  }
}

return {
  ...$input.first().json,
  weather: {
    temperature_f: temp,
    conditions: conditions,
    multiplier: multiplier,
    reasoning: reasoning
  }
};

// Simulate traffic data
const data = $input.first().json;
const hour = new Date().getHours();

let level = 'light';
let multiplier = 1.0;
let reasoning = 'Normal traffic';

if ((hour >= 7 && hour <= 9) || (hour >= 16 && hour <= 18)) {
  level = 'heavy';
  multiplier = 1.35;
  reasoning = 'Rush hour';
} else if (hour >= 11 && hour <= 14) {
  level = 'moderate';
  multiplier = 1.15;
  reasoning = 'Lunch traffic';
}

return {
  ...data,
  traffic: {
    level: level,
    multiplier: multiplier,
    reasoning: reasoning
  }
};

// Calculate final pricing multiplier
const items = $input.all();
const data = items[0]?.json || {};

const weatherMult = data.weather?.multiplier || 1.0;
const trafficMult = data.traffic?.multiplier || 1.0;

// Combine multipliers (not strictly multiplicative to avoid extreme prices)
const combined = 1 + ((weatherMult - 1) + (trafficMult - 1)) * 0.8;
const finalMultiplier = Math.round(Math.min(combined, 2.5) * 100) / 100;

const reasons = [];
if (data.weather?.reasoning !== 'Normal weather') reasons.push(data.weather.reasoning);
if (data.traffic?.reasoning !== 'Normal traffic') reasons.push(data.traffic.reasoning);

return {
  city: data.city,
  origin: data.origin,
  destination: data.destination,
  distance_miles: data.distance_miles,
  weather: data.weather,
  traffic: data.traffic,
  pricing: {
    base_multiplier: 1.0,
    weather_multiplier: weatherMult,
    traffic_multiplier: trafficMult,
    final_multiplier: finalMultiplier,
    reasoning: reasons.length > 0 ? reasons.join('; ') : 'Standard pricing conditions'
  },
  timestamp: new Date().toISOString()
};
